```

`sysfs_remove_link(&dev->kobj, "typec")` → `sysfs_remove_link(kobj, name)`:
```c
void sysfs_remove_link(struct kobject *kobj, const char *name)
{
	struct kernfs_node *parent = NULL; or kobj->sd;
	if (kobj)
		parent = kobj->sd;
